const mats={road:mat(0x303b3b),side:mat(0xbeb9a8),grass:mat(0x829b72),sand:mat(0xd5c29a),sea:mat(0x4c9fa7),white:mat(0xe4ddca),yellow:mat(0xe7bd50),dark:mat(0x182424),glass:new THREE.MeshStandardMaterial({color:0x79a9a9,roughness:.3,metalness:.1}),bike:mat(0xf47743,.45),blue:mat(0x268ba1,.4),leaf:mat(0x597c52),bark:mat(0x69513a)};
function box(parent,x,y,z,w,h,d,m,cast=true){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o}
function cyl(parent,x,y,z,r1,r2,h,m,segs=10){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segs),m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function ground(){const g=new THREE.Mesh(new THREE.PlaneGeometry(300,300),mats.grass);g.rotation.x=-Math.PI/2;g.position.y=-.12;g.receiveShadow=true;scene.add(g);
 // Rio's Atlantic edge and sandy arc
 const sea=new THREE.Mesh(new THREE.PlaneGeometry(100,300),mats.sea);sea.rotation.x=-Math.PI/2;sea.position.set(132,-.08,0);scene.add(sea);const beach=new THREE.Mesh(new THREE.PlaneGeometry(19,300),mats.sand);beach.rotation.x=-Math.PI/2;beach.position.set(81,-.04,0);scene.add(beach);
 // city streets in a compact grid
 for(let n=-4;n<=4;n++){let p=n*32;const a=box(scene,p,.005,0,9,.03,270,mats.road,false);a.receiveShadow=true;const b=box(scene,0,.006,p,270,.03,9,mats.road,false);b.receiveShadow=true;
  for(let t=-120;t<125;t+=12){box(scene,p,.025,t, .12,.012,4.2,mats.yellow,false);box(scene,t,.025,p,4.2,.012,.12,mats.yellow,false)}
  box(scene,p+5,.01,0,1.15,.04,270,mats.side,false);box(scene,p-5,.01,0,1.15,.04,270,mats.side,false);box(scene,0,.01,p+5,270,.04,1.15,mats.side,false);box(scene,0,.01,p-5,270,.04,1.15,mats.side,false);
 }
 // Curved pavement along the shore
 for(let i=0;i<38;i++){let z=-145+i*8;const trunk=cyl(scene,68,1.05,z,.2,.29,2.1,mats.bark,7);let crown=new THREE.Mesh(new THREE.ConeGeometry(1.7,3.1,7),mats.leaf);crown.position.set(68,3.3,z);crown.castShadow=true;scene.add(crown)}
 // urban blocks with colorful facades, roof details and balconies
 const colors=[0xd5ad83,0xc3b89e,0x96a995,0xd18c68,0x87999a,0xe1cfaa,0xa98972,0xb7c5b2,0xd6c6ab];
 let seed=41;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
 for(let x=-112;x<=112;x+=16)for(let z=-112;z<=112;z+=16){if(Math.abs(x%32)<8&&Math.abs(z%32)<8)continue;if(x>73)continue;if(Math.hypot(x,z)<18)continue;
  const w=10+rand()*3,d=10+rand()*3,h=5+rand()*18;const color=colors[Math.floor(rand()*colors.length)];const b=box(scene,x,h/2,z,w,h,d,mat(color),true);b.userData.building=true;
  // rooftop parapet, facade awning and windows
  box(scene,x,h+.18,z,w+.15,.35,d+.15,mat(0x9a927f),false);
  for(let floor=2.2;floor<h-1;floor+=2.5){for(let side=-1;side<=1;side+=2){const win=box(scene,x+side*(w/2+.012),floor,z,.08,.92,d*.67,mats.glass,false);win.material=win.material.clone();win.material.color.setHex(0x618789);}}
  if(rand()>.56){const sign=box(scene,x,h*.48,z+d/2+.09,2.2,.48,.12,mat(rand()>.5?0xd66f45:0x318e86),false)}
 }
 // hills framing Rio
 for(let i=0;i<9;i++){let x=-108+i*22,z=116+rand()*24,r=15+rand()*13,h=15+rand()*18;const hill=new THREE.Mesh(new THREE.ConeGeometry(r,h,7),mat(i%2?0x536e59:0x617b5d));hill.position.set(x,h/2-1,z);hill.rotation.y=rand();hill.receiveShadow=true;scene.add(hill)}
 // Sugarloaf silhouette and Christ landmark on a hill
 const peak=new THREE.Mesh(new THREE.ConeGeometry(16,31,9),mat(0x657861));peak.position.set(-85,14,-78);scene.add(peak);
 const mountain=new THREE.Mesh(new THREE.ConeGeometry(19,34,8),mat(0x547256));mountain.position.set(64,15,-97);scene.add(mountain);
 const statue=new THREE.Group();cyl(statue,0,1.2,0,.65,.7,2.4,mat(0xeee2ca),8);box(statue,0,2.7,0,5.7,.35,.35,mat(0xeee2ca));box(statue,0,3.6,0,.8,1.6,.65,mat(0xeee2ca));cyl(statue,0,4.6,0,.28,.3,.45,mat(0xeee2ca),8);statue.position.set(64,31,-97);scene.add(statue);
}
ground();
function makeBike(color=0xf47743){const g=new THREE.Group(),paint=mat(color,.42),rubber=mat(0x202728),metal=mat(0x778383,.48);for(const z of [-1.05,1]){const wheel=new THREE.Mesh(new THREE.TorusGeometry(.37,.105,8,16),rubber);wheel.rotation.y=Math.PI/2;wheel.position.set(0,.42,z);wheel.castShadow=true;g.add(wheel);const hub=cyl(g,0,.42,z,.14,.14,.2,metal,12);hub.rotation.x=Math.PI/2}box(g,0,.82,0,.48,.45,1.25,paint);box(g,0,1.1,-.38,.68,.18,.52,mat(0x1c2425));box(g,0,.66,.72,.28,.32,.4,metal);box(g,0,1.19,.9,.42,.13,.16,mat(0xf4dd9a));const handle=box(g,0,1.37,.68,1,.08,.08,metal);g.userData.kind='bike';return g}
function makeCar(color=0xd7d3c4,police=false){const g=new THREE.Group(),body=mat(color,.5),glass=mats.glass,wheels=mat(0x1d2426);box(g,0,.72,0,2.1,.72,4.1,body);box(g,0,1.34,-.1,1.68,.74,2.05,glass);box(g,0,1.37,1.4,1.68,.4,.72,body);box(g,0,.95,2.05,1.72,.24,.1,mat(0xf3dc9c));box(g,0,.95,-2.05,1.72,.24,.1,mat(0xff5d4b));for(const x of [-1,1])for(const z of [-1.35,1.35]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.42,.42,.24,12),wheels);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.43,z);wheel.castShadow=true;g.add(wheel)}if(police){box(g,0,1.78,-.15,.88,.16,.34,mat(0xdce9eb));box(g,-.28,1.9,-.15,.25,.13,.26,mat(0x3c9bff));box(g,.28,1.9,-.15,.25,.13,.26,mat(0xff5448))}g.userData.kind='car';return g}
function makePerson(shirt=0xf47743){const g=new THREE.Group();cyl(g,0,.86,0,.24,.3,.82,mat(shirt),9);const head=new THREE.Mesh(new THREE.SphereGeometry(.22,10,8),mat(0x9c684e));head.position.y=1.48;head.castShadow=true;g.add(head);box(g,-.13,.32,0,.16,.64,.19,mat(0x273b3d));box(g,.13,.32,0,.16,.64,.19,mat(0x273b3d));return g}
const worldObjects=[];const vehicles=[];function addCar(x,z,color,rotation=0){const v=makeCar(color);v.position.set(x,0,z);v.rotation.y=rotation;scene.add(v);vehicles.push(v);worldObjects.push(v);return v}
// Parked cars visible along blocks
for(const [x,z,c,r] of [[-18,-20,0xd9c38b,0],[-48,22,0x739c9b,Math.PI/2],[49,23,0xb8a0a4,Math.PI/2],[-18,48,0xe4e1d4,0],[16,-50,0x557c9c,0],[-51,-50,0xd3a079,Math.PI/2],[48,-51,0x96a88c,Math.PI/2],[-80,2,0xc7c5bc,0],[18,82,0xb98d73,0]])addCar(x,z,c,r);
// mission points
const points={deliveryStart:new THREE.Vector3(-15,0,-15),deliveryEnd:new THREE.Vector3(-48,0,47),taxiStart:new THREE.Vector3(49,0,47),taxiEnd:new THREE.Vector3(17,0,-49),school:new THREE.Vector3(-48,0,-47),chop:new THREE.Vector3(-80,0,80),carTarget:new THREE.Vector3(49,0,-50)};
function marker(color=0xff925e){const g=new THREE.Group();const ring=new THREE.Mesh(new THREE.TorusGeometry(1.5,.1,8,24),new THREE.MeshBasicMaterial({color}));ring.rotation.x=Math.PI/2;ring.position.y=.12;g.add(ring);const beam=new THREE.Mesh(new THREE.CylinderGeometry(.08,.38,3,12,1,true),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.22,side:THREE.DoubleSide}));beam.position.y=1.6;g.add(beam);const diamond=new THREE.Mesh(new THREE.OctahedronGeometry(.35),new THREE.MeshBasicMaterial({color}));diamond.position.y=3.1;g.add(diamond);return g}
let targetMarker=marker();targetMarker.visible=false;scene.add(targetMarker);
let player=makePerson(0xf47743);player.position.set(0,0,0);scene.add(player);let bike=makeBike();bike.position.set(0,0,3);scene.add(bike);let activeVehicle=null,vehicleType='bike',avatarColor=0xf47743;
let police=[];for(let i=0;i<2;i++){let g=makeCar(0xe8e8df,true);g.position.set(i?75:-75,0,i?-70:70);g.rotation.y=i?Math.PI/2:0;scene.add(g);police.push({mesh:g,speed:0})}
// pedestrians add life to sidewalks
for(let i=0;i<15;i++){let p=makePerson([0xd58b61,0x56a4a4,0xd2c46b,0x9b85ad][i%4]);p.position.set(-60+(i*29)%120,0,-95+((i*37)%180));scene.add(p);p.userData.walkOffset=i}
// animated traffic cars
const traffic=[];for(let i=0;i<5;i++){const c=makeCar([0x78918c,0xb69b81,0xd1d2c4,0x7895aa][i%4]);c.position.set(-94+i*38,0,12+(i%2)*32);c.rotation.y=Math.PI/2;scene.add(c);traffic.push({mesh:c,axis:'x',speed:3+i%3,dir:1})}
let money=250,rep=0,wanted=0,licenseA=false,licenseB=false,started=false,job=null,jobStage=0,vehicleSpeed=0,fuel=100,selectedWeapon=0;const weaponNames=['DESARMADO','PISTOLA','ESCOPETA','SMG'];let active=false;
const keys={};addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='KeyF')toggleVehicle();if(e.code==='KeyE')interact();if(e.code==='KeyQ')cycleWeapon();if(e.code==='Escape')togglePause();});addEventListener('keyup',e=>keys[e.code]=false);addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
let lastShot=0;addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;fireWeapon()});
function toast(t){$('#toastText').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2700)}
function setMoney(n){money=Math.max(0,money+n);$('#money').textContent='R$ '+money.toLocaleString('pt-BR');$('#pauseMoney').textContent='R$ '+money.toLocaleString('pt-BR')}
function setWanted(n){wanted=Math.max(0,Math.min(5,n));$('#wanted b').textContent='★'.repeat(wanted)+'☆'.repeat(5-wanted);$('#wanted').classList.toggle('hot',wanted>0)}
function cycleWeapon(){selectedWeapon=(selectedWeapon+1)%weaponNames.length;$('#weaponChip b').textContent=weaponNames[selectedWeapon];toast('Equipamento: '+weaponNames[selectedWeapon])}
function fireWeapon(){if(!started||selectedWeapon===0)return;const now=performance.now();if(now-lastShot<350)return;lastShot=now;setWanted(Math.max(1,wanted));const origin=activeVehicle?activeVehicle.position.clone():player.position.clone();origin.y+=activeVehicle?.9:1.35;const dir=new THREE.Vector3(Math.sin(activeVehicle?activeVehicle.rotation.y:player.rotation.y),0,Math.cos(activeVehicle?activeVehicle.rotation.y:player.rotation.y));const end=origin.clone().add(dir.multiplyScalar(24));const geom=new THREE.BufferGeometry().setFromPoints([origin,end]);const line=new THREE.Line(geom,new THREE.LineBasicMaterial({color:0xffdf84}));scene.add(line);setTimeout(()=>{scene.remove(line);geom.dispose()},90);toast('Disparo! A polícia foi alertada.')}
function toggleVehicle(){if(!started)return;if(activeVehicle){const pos=activeVehicle.position.clone();pos.x+=Math.cos(activeVehicle.rotation.y)*1.8;pos.z-=Math.sin(activeVehicle.rotation.y)*1.8;player.position.copy(pos);player.visible=true;activeVehicle.userData.occupied=false;activeVehicle=null;vehicleSpeed=0;updateRide();toast('Você saiu do veículo.');return}let nearest=null,dist=4;for(const v of vehicles){if(v.userData.occupied)continue;const d=v.position.distanceTo(player.position);if(d<dist){nearest=v;dist=d}}if(bike.position.distanceTo(player.position)<dist){nearest=bike;dist=bike.position.distanceTo(player.position)}if(nearest){if(nearest!==bike&&!licenseB){toast('Você precisa da CNH B para dirigir carros.');return}activeVehicle=nearest;vehicleType=nearest.userData.kind;nearest.userData.occupied=true;player.visible=false;updateRide();if(nearest!==bike&&nearest!==police[0]?.mesh&&nearest!==police[1]?.mesh){setWanted(Math.max(1,wanted));toast('Veículo levado! A polícia está procurando você.')}else toast('Boa viagem!');return}toast('Chegue mais perto de um veículo.')}
function updateRide(){const h=$('#rideHud');h.classList.toggle('show',!!activeVehicle);$('#rideName').textContent=vehicleType==='bike'?'STREET 160':'SEDAN URBANO';$('#rideStatus').textContent=vehicleType==='bike'?'LIVRE · REGULADA':(licenseB?'CNH B · REGULAR':'SEM HABILITAÇÃO')}
function beginJob(type){if(job){toast('Finalize o trabalho atual primeiro.');return}if(type==='license-moto'||type==='license-car'){if(type==='license-car'&&!licenseA){toast('Conquiste a CNH A antes de fazer a prova B.');return}const cost=type==='license-moto'?50:100;if(money<cost){toast('Saldo insuficiente para pagar a inscrição.');return}setMoney(-cost);job=type;jobStage=0;const p=points.school;setTarget(p,'AUTOESCOLA · PROVA PRÁTICA','Chegue à autoescola e faça o circuito.');toast('Inscrição confirmada. Siga o marcador até a autoescola.');$('#jobsModal').classList.add('hidden');return}
 job=type;jobStage=0;$('#jobsModal').classList.add('hidden');if(type==='delivery'){setTarget(points.deliveryStart,'ENTREGA EXPRESSA · RETIRADA','Retire o pedido no Largo da Carioca.');toast('Pedido aceito! Pegue a encomenda no marcador.')}if(type==='taxi'){setTarget(points.taxiStart,'RÁDIO-TÁXI · PASSAGEIRO','Busque seu passageiro em Ipanema.');toast('Corrida aceita! Passageiro aguardando em Ipanema.')}if(type==='chop'){setTarget(points.carTarget,'SERVIÇO SUJO · ALVO','Recupere o sedan e leve-o ao ferro-velho.');toast('Carro identificado. A polícia pode notar o furto.')}}
function setTarget(pos,title,desc){targetMarker.position.copy(pos);targetMarker.visible=true;$('#missionType').textContent=title.split(' · ')[0];$('#missionTitle').textContent=title;$('#missionDesc').textContent=desc;$('#missionReward').textContent=job==='license-moto'?'APROVAÇÃO · CATEGORIA A':job==='license-car'?'APROVAÇÃO · CATEGORIA B':job==='delivery'?'PAGAMENTO · R$ 85':job==='taxi'?'PAGAMENTO · R$ 140':'PAGAMENTO · R$ 320';$('#missionBtn').textContent='CANCELAR TRABALHO  ×'}
function finishJob(){const old=job;job=null;jobStage=0;targetMarker.visible=false;rep++;$('#rep').textContent=rep>=6?'LENDÁRIO':rep>=3?'CONHECIDO':'NOVATO';if(old==='delivery'){setMoney(85);toast('Entrega concluída! + R$ 85')}if(old==='taxi'){setMoney(140);toast('Corrida concluída! + R$ 140')}if(old==='chop'){setMoney(320);setWanted(Math.max(0,wanted-1));toast('Peças vendidas! + R$ 320. Limpe seu nome.')}if(old==='license-moto'){licenseA=true;$('#licenseA').textContent='CONQUISTADA';toast('CNH A conquistada! Agora você pilota legalmente.')}if(old==='license-car'){licenseB=true;$('#licenseB').textContent='CONQUISTADA';toast('CNH B conquistada! Agora pode dirigir carros.')}$('#missionType').textContent='CIDADE ABERTA';$('#missionTitle').textContent='Qual é o próximo passo?';$('#missionDesc').textContent='Escolha um trabalho ou explore o Rio por conta própria.';$('#missionReward').textContent='NOVAS OPORTUNIDADES NO MAPA';$('#missionBtn').textContent='VER TRABALHOS  ↗'}
function interact(){if(!started)return;if(job==='license-moto'||job==='license-car'){if(player.position.distanceTo(points.school)<6||(activeVehicle&&activeVehicle.position.distanceTo(points.school)<6)){finishJob();return}}
 if(job==='delivery'){if(jobStage===0&&player.position.distanceTo(points.deliveryStart)<6){jobStage=1;setTarget(points.deliveryEnd,'ENTREGA EXPRESSA · DESTINO','Pedido na mochila. Leve até a Lapa.');toast('Pedido retirado! Entregue na Lapa.')}else if(jobStage===1&&player.position.distanceTo(points.deliveryEnd)<6)finishJob();else toast('Siga até o marcador laranja.');return}
 if(job==='taxi'){if(jobStage===0&&player.position.distanceTo(points.taxiStart)<7){jobStage=1;setTarget(points.taxiEnd,'RÁDIO-TÁXI · DESTINO','Passageiro a bordo. Siga até Copacabana.');toast('Passageiro embarcou. Boa corrida!')}else if(jobStage===1&&player.position.distanceTo(points.taxiEnd)<7)finishJob();else toast('Siga até o marcador da corrida.');return}
 if(job==='chop'){if(jobStage===0){const target=vehicles.find(v=>v.position.distanceTo(points.carTarget)<8);if(target&&player.position.distanceTo(target.position)<5){activeVehicle=target;target.userData.occupied=true;player.visible=false;vehicleType='car';jobStage=1;setWanted(Math.max(2,wanted));updateRide();setTarget(points.chop,'FERRO-VELHO · ENTREGA','Leve o carro roubado até o desmanche.');toast('Carro recuperado. Fuja para o ferro-velho!')}else toast('Encontre o sedan marcado e pressione F para entrar.')}else if(activeVehicle&&activeVehicle.position.distanceTo(points.chop)<9)finishJob();return}
 if(player.position.distanceTo(points.school)<7){$('#jobsModal').classList.remove('hidden');return}toast('Explore a cidade ou abra TRABALHOS para aceitar um serviço.')}
$('#missionBtn').onclick=()=>{if(job){job=null;targetMarker.visible=false;$('#missionTitle').textContent='Trabalho cancelado';$('#missionDesc').textContent='Sua cidade. Explore ou escolha outra oportunidade.';$('#missionType').textContent='CIDADE ABERTA';$('#missionBtn').textContent='VER TRABALHOS  ↗';toast('Trabalho cancelado.')}else $('#jobsModal').classList.remove('hidden')};

